#pragma mark - map object references to number

std::mutex globalMutex;

typedef const void *xls_handle;
std::map<uint32_t, xls_handle> __handles;

uint32_t __handleSet(xls_handle h){
	
	std::lock_guard<std::mutex> lock(globalMutex);
	
	uint32_t i = 1;
	
	while (__handles.find(i) != __handles.end()) {
		i++;
	}
	
	__handles.insert(std::map<uint32_t, xls_handle>::value_type(i, h));
	
	return i;
}

xls_handle __handleGet(uint32_t i){
	
	std::lock_guard<std::mutex> lock(globalMutex);
	
	xls_handle h = NULL;
	
	std::map<uint32_t, xls_handle>::iterator pos = __handles.find(i);
	
	if(pos != __handles.end()) {
		h = pos->second;
	}
	
	return h;
}

void __handleClear(uint32_t i){
	
	std::lock_guard<std::mutex> lock(globalMutex);
	
	xls_handle h = NULL;
	
	std::map<uint32_t, xls_handle>::iterator pos = __handles.find(i);
	
	if(pos != __handles.end()) {
		h = pos->second;
		__handles.erase(pos);
	}
}

#pragma mark -

void PluginMain(PA_long32 selector, PA_PluginParameters params)
{
	PA_long32 pProcNum = selector;
	sLONG_PTR *pResult = (sLONG_PTR *)params->fResult;
	PackagePtr pParams = (PackagePtr)params->fParameters;

	try
	{
		CommandDispatcher(pProcNum, pResult, pParams);
	}
	catch(...)
	{
		// Every command in manifest.json declares a ":L" return value, so 4D
		// is always waiting on *pResult. If a handler throws before it calls
		// returnValue.setReturn(pResult) (e.g. std::bad_alloc from the handle
		// map or a string wrapper), swallowing the exception here without
		// still writing *pResult would leave the host waiting forever for a
		// return that never comes -- a freeze, not just a lost error code.
		// Writing a sentinel value here guarantees a return happens on every
		// path, even ones we didn't anticipate inside a specific handler.
		if(pResult){
			*pResult = (sLONG_PTR)FREEXL_INSUFFICIENT_MEMORY;
		}
	}
}

void CommandDispatcher (PA_long32 pProcNum, sLONG_PTR *pResult, PackagePtr pParams)
{
	switch(pProcNum)
	{
			// --- FreeXL
			
		case 1 :
			FreeXL_Get_worksheet_name(pResult, pParams);
			break;
			
		case 2 :
			FreeXL_Get_info(pResult, pParams);
			break;
			
		case 3 :
			FreeXL_Close(pResult, pParams);
			break;
			
		case 4 :
			FreeXL_Open_info(pResult, pParams);
			break;
			
		case 5 :
			FreeXL_Open(pResult, pParams);
			break;
			
		case 6 :
			FreeXL_Set_active_worksheet(pResult, pParams);
			break;
			
		case 7 :
			FreeXL_Get_active_worksheet(pResult, pParams);
			break;
			
		case 8 :
			FreeXL_Worksheet_dimensions(pResult, pParams);
			break;
			
		case 9 :
			FreeXL_Get_cell_value(pResult, pParams);
			break;
			
	}
}

